document.addEventListener('focusin',e=>{if(!featureActive())return;if(e.target.id==='sb-goal')flFlag('goalSeen');if(e.target.id==='prompt-result')flFlag('resultSeen');});
document.addEventListener('input',e=>{if(!featureActive())return;const t=featureSession();if(e.target.id==='as-input'&&e.target.value.trim())flFlag(t.step===1?'followup':'request');if(e.target.id==='prompt-original'){originalPrompt=e.target.value;t.prompt={original:originalPrompt,result:refineResult};if(e.target.value.trim())flFlag('promptEdited');save();}if(e.target.id==='prompt-result'&&refineResult){refineResult.text=e.target.value;t.prompt={original:originalPrompt,result:refineResult};save();}});
document.addEventListener('click',e=>{if(!featureActive()&&!e.target.closest('[data-learn="offline"]'))return;const b=e.target.closest('button,summary');if(!b)return;const t=featureSession();if(b.hasAttribute('data-as-pause')&&AS.ac)flFlag('paused');if(b.hasAttribute('data-as-send'))flFlag('executionClicked');if(b.dataset.sb==='goal')flFlag('goalSaved');if(b.dataset.sb==='back')flFlag('returned');if(b.matches('.sb-update-details>summary'))flFlag('updatesViewed');if(b.dataset.sb==='status')flFlag('statusViewed');if(b.hasAttribute('data-auth-refresh'))flFlag('authViewed');if(b.matches('.learning-auth-scenario>summary'))flFlag('scenario');if(b.hasAttribute('data-util-close')&&t?.step===5)flFlag('promptClosed');if(b.hasAttribute('data-activity-board'))flFlag('progressViewed');
 if(b.dataset.learnAuth){e.preventDefault();const k=b.dataset.learnAuth;if(k==='verify')flFlag('authVerified');if(k==='resume'&&t.learn.authVerified)flFlag('authResumed');if(k==='cancel'&&t.learn.authResumed)flFlag('authCanceled');const text=utility.querySelector('[data-learn-auth-state]');if(text)text.textContent=t.learn.authCanceled?'已取消1个教学任务，其余2个保留各自断点。':t.learn.authResumed?'3个教学任务已从各自断点接续。':t.learn.authVerified?'已模拟本人验证完成，等待你明确接续。':'请先完成本人验证。';return;}
 if(!b.dataset.learn)return;e.preventDefault();switch(b.dataset.learn){case'previous':if(t.step>0){if(AS.ac&&asSession()?.boardId===t.boardId)asPause();asCloseAux();$('#guide').classList.remove('o');t.step--;save();renderAll();featurePaint();}break;case'offline':void featureBegin('offline');break;case'demo':flFlag('request');flFlag('executionClicked');if(t.step===1){const s={id:'as'+uid(),demo:true,boardId:t.boardId,request:'固定本地暂停练习',steps:[{id:'s1',name:'assistant.demo',label:'本地整理过程，可暂停接续',args:{},effect:'local',status:'pending'}],cursor:0,status:'ready',createdAt:Date.now()};state.assistantSessions.push(s);t.assistantId=s.id;AS.current=s.id;void asExecute(s);}else void featureDemo();break;case'next':if(!featureDone())return;if(t.step===7){featureFinish();return;}asCloseAux();$('#guide').classList.remove('o');t.step++;if([4,5].includes(t.step)&&P(t.projectId))state.sel=t.projectId;save();renderAll();featurePaint();break;case'locate':{const current=FeatureLearningCore.plan(t,flView(t)).find(o=>!o.done),target=current&&document.querySelector(current.selector);if(target){target.scrollIntoView({block:'nearest',inline:'nearest'});target.focus({preventScroll:true});flDraw();}else hint('先按当前说明打开对应面板；箭头只会指向可见的真实控件。');break;}}
},true);
let flFrame=null;function flQueue(){if(flFrame)return;flFrame=requestAnimationFrame(()=>{flFrame=null;if(featureActive())featurePaint()});}document.addEventListener('click',flQueue);document.addEventListener('change',flQueue);document.addEventListener('scroll',()=>{if(featureActive())flDraw()},true);window.addEventListener('resize',flQueue);setInterval(()=>{if(featureActive())flQueue()},500);
/* FEATURE_LEARNING_END */
